scripts.xorshift32_solver:
def solve(inputs: dict) -> float:
    x = int(inputs['X']) & 0xFFFFFFFF
    for _ in range(int(inputs['K'])):
        x ^= (x << inputs['A']) & 0xFFFFFFFF
        x ^= x >> inputs['B']
        x ^= (x << inputs['C']) & 0xFFFFFFFF
        x &= 0xFFFFFFFF
    return float(x)
